/**
 * The repository root is a thin alias bundle over the published npm aggregate:
 * its patch is the aggregate's generated manifest, while every module the rows
 * reference resolves from the `@linxin666/dsh-web-all` dependency.
 *
 * That dependency is the release-line caret `^X.Y.Z`, whose base is the release
 * tag: the shipped patch was generated by that release, and the base moves with
 * the tag, so every family release changes the spec and a lockfile recorded
 * against an earlier release no longer satisfies it.
 *
 * A spec whose base trails the tag — or any wider range that keeps satisfying an
 * older child, such as the reported `^0.3.6` — is the failure mode of issue
 * #1442: the new patch mounts rows whose subpaths the retained aggregate does
 * not export, Node throws ERR_PACKAGE_PATH_NOT_EXPORTED for every row, and the
 * plugin tree fails to load. The root therefore carries no hand-pinned literal,
 * and scripts/verify-version.mjs fails the release when the spec is anything
 * other than the tag's own caret.
 *
 * The root is private and never published, but it is the manifest a git or link
 * install of the repository reports, so its own version follows the release like
 * every family package.
 */

/** The aggregate dependency the root alias resolves every row's modules from. */
export const ROOT_AGGREGATE_DEPENDENCY = '@linxin666/dsh-web-all'

/** Narrow an untrusted manifest value to a plain record. */
const record = (value) => value !== null && typeof value === 'object' ? value : undefined

/**
 * The spec the root alias must declare for a release tag: the release-line
 * caret, so the root follows patches inside the tag's line while the base stays
 * on the release the shipped patch came from.
 * @param {string} version - release tag version, without the leading v.
 * @returns {string} the required range spec.
 */
const aggregateSpec = (version) => `^${version}`

/**
 * Check the root alias dependency against the release tag.
 * @param {unknown} rootManifest - parsed repository root package.json.
 * @param {string} version - release tag version, without the leading v.
 * @returns {string | undefined} the mismatch message, or undefined when the
 *   root declares the tag's release-line caret.
 */
export function rootAggregatePinMismatch(rootManifest, version) {
  const dependencies = record(rootManifest)?.dependencies
  const spec = record(dependencies)?.[ROOT_AGGREGATE_DEPENDENCY]
  const expected = aggregateSpec(version)
  if (spec === expected) return undefined
  return `root dependency ${ROOT_AGGREGATE_DEPENDENCY} ${typeof spec === 'string' ? spec : '(missing)'} does not match tag v${version} (expected ${expected})`
}

/**
 * Check the root alias's own version against the release tag. The root package
 * is private and never published, but a git or link install of the repository
 * reports this version — the plugin manager reads the installed manifest — so it
 * follows the release like every family package.
 * @param {unknown} rootManifest - parsed repository root package.json.
 * @param {string} version - release tag version, without the leading v.
 * @returns {string | undefined} the mismatch message, or undefined when the root
 *   carries the tag version.
 */
export function rootVersionMismatch(rootManifest, version) {
  const declared = record(rootManifest)?.version
  if (declared === version) return undefined
  return `root version ${typeof declared === 'string' ? declared : '(missing)'} does not match tag v${version}`
}
